<?php require_once __DIR__.'/includes/security.php';require __DIR__.'/includes/db.php';require __DIR__.'/includes/customer-auth.php';require_customer();$c=current_customer();$error='';$success='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='address'){ $label=trim($_POST['label']??'');$name=trim($_POST['recipient_name']??'');$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');$city=trim($_POST['city']??'');$postal=trim($_POST['postal_code']??'');$default=isset($_POST['is_default'])?1:0;if(mb_strlen($label)>60||mb_strlen($name)<2||mb_strlen($name)>120||!preg_match('/^[0-9+(). -]{6,30}$/',$phone)||mb_strlen($address)>5000||!$address||mb_strlen($city)>100||!$city||mb_strlen($postal)>15||!$postal){$error='Mohon isi data alamat dengan benar.';}else{$pdo->beginTransaction();if($default)$pdo->prepare('UPDATE customer_addresses SET is_default=0 WHERE customer_id=?')->execute([$c['id']]);$pdo->prepare('INSERT INTO customer_addresses(customer_id,label,recipient_name,phone,address,city,postal_code,is_default) VALUES(?,?,?,?,?,?,?,?)')->execute([$c['id'],$label?:'Rumah',$name,$phone,$address,$city,$postal,$default]);if(!$default){$pdo->prepare('UPDATE customer_addresses SET is_default=1 WHERE id=(SELECT id FROM (SELECT id FROM customer_addresses WHERE customer_id=? ORDER BY id LIMIT 1) x)')->execute([$c['id']]);}$pdo->commit();$success='Alamat berhasil disimpan.';}}elseif($action==='default'||$action==='delete'){$id=(int)($_POST['address_id']??0);$s=$pdo->prepare('SELECT id FROM customer_addresses WHERE id=? AND customer_id=?');$s->execute([$id,$c['id']]);if(!$s->fetchColumn()){$error='Alamat tidak ditemukan.';}elseif($action==='default'){$pdo->beginTransaction();$pdo->prepare('UPDATE customer_addresses SET is_default=0 WHERE customer_id=?')->execute([$c['id']]);$pdo->prepare('UPDATE customer_addresses SET is_default=1 WHERE id=? AND customer_id=?')->execute([$id,$c['id']]);$pdo->commit();$success='Alamat utama diperbarui.';}else{$pdo->beginTransaction();$pdo->prepare('DELETE FROM customer_addresses WHERE id=? AND customer_id=?')->execute([$id,$c['id']]);$left=$pdo->prepare('SELECT id FROM customer_addresses WHERE customer_id=? ORDER BY id LIMIT 1');$left->execute([$c['id']]);if($next=$left->fetchColumn())$pdo->prepare('UPDATE customer_addresses SET is_default=1 WHERE id=?')->execute([$next]);$pdo->commit();$success='Alamat dihapus.';}}elseif($action==='profile'){$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');if(mb_strlen($name)<2||mb_strlen($name)>120||!preg_match('/^[0-9+(). -]{6,30}$/',$phone))$error='Nama atau nomor telepon tidak valid.';else{$pdo->prepare('UPDATE customers SET name=?,phone=? WHERE id=?')->execute([$name,$phone,$c['id']]);$_SESSION['customer']['name']=$name;$_SESSION['customer']['phone']=$phone;$success='Profil diperbarui.';}}}
$s=$pdo->prepare('SELECT * FROM customer_addresses WHERE customer_id=? ORDER BY is_default DESC,id DESC');$s->execute([$c['id']]);$addresses=$s->fetchAll();$s=$pdo->prepare('SELECT id,order_number,total,status,created_at FROM orders WHERE customer_id=? ORDER BY id DESC LIMIT 20');$s->execute([$c['id']]);$orders=$s->fetchAll();?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Akun saya — TokoKita</title><link rel="stylesheet" href="assets/style.css"><style>.account-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.account-grid .field{margin:10px 0}.addr{padding:14px 0;border-bottom:1px solid #eee}.addr-actions{display:flex;gap:8px;margin-top:9px}.addr-actions form{margin:0}@media(max-width:700px){.account-grid{grid-template-columns:1fr}}</style></head><body><?php include __DIR__.'/includes/header.php'?><?php customer_nav()?><main class="wrap"><div class="crumb"><a href="index.php">Beranda</a> / Akun saya</div><h1 class="page-title">Akun saya</h1><?php if($error):?><div class="notice error"><?=e($error)?></div><?php elseif($success):?><div class="notice"><?=e($success)?></div><?php endif?><div class="account-grid"><section class="panel"><h2>Profil</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="profile"><div class="field"><label>Nama</label><input name="name" maxlength="120" required value="<?=e($c['name'])?>"></div><div class="field"><label>Email (untuk login)</label><input readonly value="<?=e($c['email'])?>"></div><div class="field"><label>Telepon</label><input name="phone" maxlength="30" required value="<?=e($c['phone'])?>"></div><button class="smallbtn">Simpan profil</button></form></section><section class="panel"><h2>Tambah alamat</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="address"><div class="field"><label>Label (Rumah/Kantor)</label><input name="label" maxlength="60" placeholder="Rumah"></div><div class="field"><label>Nama penerima</label><input name="recipient_name" maxlength="120" required value="<?=e($c['name'])?>"></div><div class="field"><label>Telepon penerima</label><input name="phone" maxlength="30" required value="<?=e($c['phone'])?>"></div><div class="field"><label>Alamat jalan, nomor, patokan</label><textarea name="address" maxlength="5000" required></textarea></div><div class="field"><label>Kota/Kabupaten</label><input name="city" maxlength="100" required></div><div class="field"><label>Kode pos</label><input name="postal_code" maxlength="15" required></div><label><input type="checkbox" name="is_default"> Jadikan alamat utama</label><button class="smallbtn" style="display:block;margin-top:12px">Simpan alamat</button></form></section></div><section class="panel" style="margin-top:18px"><h2>Alamat tersimpan</h2><?php if(!$addresses):?><p class="muted">Belum ada alamat. Tambahkan alamat untuk checkout lebih cepat.</p><?php endif?><?php foreach($addresses as $a):?><div class="addr"><b><?=e($a['label'])?></b> <?php if($a['is_default']):?><span class="status-pill">Utama</span><?php endif?><div><?=e($a['recipient_name'])?> · <?=e($a['phone'])?><br><?=nl2br(e($a['address']))?><br><?=e($a['city'])?> <?=e($a['postal_code'])?></div><div class="addr-actions"><?php if(!$a['is_default']):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="default"><input type="hidden" name="address_id" value="<?=$a['id']?>"><button class="smallbtn">Jadikan utama</button></form><?php endif?><form method="post" onsubmit="return confirm('Hapus alamat ini?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="address_id" value="<?=$a['id']?>"><button class="smallbtn danger">Hapus</button></form></div></div><?php endforeach?></section><section class="panel" style="margin-top:18px"><h2>Pesanan saya</h2><div class="tablewrap"><table class="admintable"><thead><tr><th>No pesanan</th><th>Tanggal</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><?=e($o['order_number'])?></td><td><?=e($o['created_at'])?></td><td><?=rupiah($o['total'])?></td><td><?=e($o['status'])?></td></tr><?php endforeach?><?php if(!$orders):?><tr><td colspan="4">Belum ada pesanan.</td></tr><?php endif?></tbody></table></div></section></main><?php include __DIR__.'/includes/footer.php'?></body></html>